def count_Substrings(s):
    count = 0
    n = len(s)
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            substring = s[start:start + length]
            digit_sum = sum(int(digit) for digit in substring)
            if digit_sum == length:
                count += 1
    return count
```

