        if left >= right:
            return 0

        mid = (left + right) // 2
        inv_count = merge_sort_and_count(arr, left, mid)
        inv_count += merge_sort_and_count(arr, mid + 1, right)
        inv_count += merge_and_count(arr, left, mid, right)
        return inv_count

